"""Contract tests for Gemini Call 1 (Extract) output schema.

Authority: docs/architecture/C-gemini-architecture.md §53-C
"""

from __future__ import annotations

import json

import pytest
from pydantic import ValidationError

from backend.staymad.llm.deterministic_client import DeterministicGeminiClient
from backend.staymad.llm.schemas import (
    ExtractedClaim,
    ExtractInput,
    ExtractResponse,
)


def test_gemini_extract_json_schema_structure():
    """Verify JSON schema generated by Pydantic conforms to C-gemini-architecture.md."""
    schema = ExtractResponse.model_json_schema()

    assert schema["type"] == "object"
    props = schema["properties"]

    assert "schema_version" in props
    assert "article_version_id" in props
    assert "suggested_category" in props
    assert "claims" in props
    assert "entities" in props
    assert "insufficient_content" in props

    # Check suggested_category allowed enums
    cat_field = props["suggested_category"]
    assert "enum" in cat_field
    assert set(cat_field["enum"]) == {
        "DISASTER_AND_WEATHER",
        "TRANSPORTATION_AND_INFRASTRUCTURE",
        "GOVERNMENT_AND_PUBLIC_POLICY",
        "UNKNOWN",
    }

    # Check claim item schema
    claim_schema = ExtractResponse.model_fields["claims"].annotation
    assert claim_schema is not None


def test_extracted_claim_enforces_source_span_length():
    """Claim source_span must not exceed 200 characters."""
    valid_claim = ExtractedClaim(
        claim_text="Banjir melanda Cipinang Melayu setinggi 1 meter.",
        source_span="Banjir melanda Cipinang Melayu setinggi 1 meter.",
        extraction_confidence=0.95,
    )
    assert valid_claim.source_span is not None

    with pytest.raises(ValidationError):
        ExtractedClaim(
            claim_text="Teks klaim",
            source_span="A" * 205,  # Exceeds max 200
            extraction_confidence=0.9,
        )


def test_deterministic_client_extract_contract():
    client = DeterministicGeminiClient()
    input_data = ExtractInput(
        article_version_id="11111111-2222-3333-4444-555555555555",
        source_id="22222222-3333-4444-5555-666666666666",
        source_tier="TIER_1",
        source_family="GOV_BPBD_DKI",
        title="BPBD DKI: Lima Kecamatan di Jaktim Terendam Banjir",
        excerpt="BPBD DKI Jakarta melaporkan sebanyak lima kecamatan di Jakarta Timur terendam banjir pada Sabtu pagi sekitar pukul 08:30 WIB akibat luapan Kali Ciliwung.",
        published_time="2026-10-10T09:00:00+07:00",
        source_url="https://bpbd.jakarta.go.id/berita/440101",
    )

    response = client.extract(input_data)
    assert isinstance(response, ExtractResponse)
    assert response.schema_version == "1.0"
    assert response.article_version_id == input_data.article_version_id
    assert response.suggested_category == "DISASTER_AND_WEATHER"
    assert len(response.claims) > 0

    for c in response.claims:
        assert len(c.source_span) <= 200
        assert 0.0 <= c.extraction_confidence <= 1.0
        assert c.event_time_precision in (
            "EXACT",
            "APPROXIMATE",
            "DAY",
            "RANGE",
            "UNKNOWN",
        )

    # Serialize to JSON and deserialize to guarantee valid JSON wire format
    json_str = response.model_dump_json()
    parsed = json.loads(json_str)
    assert parsed["suggested_category"] == "DISASTER_AND_WEATHER"
    assert parsed["schema_version"] == "1.0"
